PRAGMA foreign_keys=ON;
CREATE TABLE students(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 50), yomi TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE months(month TEXT PRIMARY KEY CHECK(length(month)=7), published INTEGER NOT NULL DEFAULT 0 CHECK(published IN(0,1)), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE calendar(date TEXT PRIMARY KEY CHECK(date(date)=date), closed INTEGER NOT NULL DEFAULT 0 CHECK(closed IN(0,1)), pattern TEXT NOT NULL DEFAULT 'default' CHECK(pattern IN('default','temporary','temporary2')), reason TEXT NOT NULL DEFAULT '');
CREATE TABLE subjects(pattern TEXT NOT NULL CHECK(pattern IN('default','temporary','temporary2')), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), period INTEGER NOT NULL CHECK(period BETWEEN 1 AND 6), subject TEXT NOT NULL DEFAULT '個', PRIMARY KEY(pattern,weekday,period));
CREATE TABLE templates(month TEXT NOT NULL REFERENCES months(month), student_id TEXT NOT NULL REFERENCES students(id), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), period INTEGER NOT NULL CHECK(period BETWEEN 1 AND 6), PRIMARY KEY(month,student_id,weekday,period));
CREATE TABLE reservations(student_id TEXT NOT NULL REFERENCES students(id), date TEXT NOT NULL CHECK(date(date)=date), period INTEGER NOT NULL CHECK(period BETWEEN 1 AND 6), PRIMARY KEY(student_id,date,period));
CREATE INDEX reservations_date ON reservations(date,period);
CREATE TABLE announcements(id TEXT PRIMARY KEY, text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 2000), created_at TEXT NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN('student','teacher')), student_id TEXT REFERENCES students(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE login_events(id INTEGER PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(id), created_at TEXT NOT NULL);
CREATE INDEX login_events_date ON login_events(created_at);
CREATE TABLE write_guards(id TEXT PRIMARY KEY, ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE site_content(id TEXT PRIMARY KEY CHECK(id='home'), data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE migration_mapping(source_path TEXT PRIMARY KEY, actual_date TEXT, hash TEXT NOT NULL, rule TEXT NOT NULL);
WITH RECURSIVE days(n) AS (SELECT 0 UNION ALL SELECT n+1 FROM days WHERE n<6), periods(n) AS(SELECT 1 UNION ALL SELECT n+1 FROM periods WHERE n<6), patterns(p) AS(SELECT 'default' UNION ALL SELECT 'temporary' UNION ALL SELECT 'temporary2') INSERT INTO subjects SELECT p,days.n,periods.n,'個' FROM patterns,days,periods;
INSERT INTO site_content VALUES('home','{}');
